// 1. Verificar código de estado HTTP
pm.test("Status code should be 200 (OK)", function () {
    pm.response.to.have.status(200);
});

// 2. Parsear respuesta
const response = pm.response.json();

// 3. Definir datos esperados (basados en el evento RabbitMQ)
const expectedInvoice = {
    factCode: "2024001",         
    thirdId: 456,
    totalValue: 200000,
    pendingValue: 150000,
    creationDate: "2024-07-01",
    expirationDate: "2025-07-15"
};

// 4. Validar estructura general
pm.test("Response follows ApiResponse success structure", function () {
    pm.expect(response.success).to.be.true;
    pm.expect(response.code).to.eql("OK");
    pm.expect(response.data).to.be.an('array').that.is.not.empty;
});

// 5. Obtener la factura retornada
const invoice = response.data.find(i => i.factCode === expectedInvoice.factCode);

// 6. Verificar que la factura exista
pm.test("Invoice sent by RabbitMQ exists in API response", function () {
    pm.expect(invoice, "Invoice not found in API response").to.exist;
});

// 7. Comparar valores campo a campo
pm.test("Invoice data matches RabbitMQ event data", function () {
    pm.expect(invoice.factCode).to.eql(expectedInvoice.factCode);
    pm.expect(invoice.thirdId).to.eql(expectedInvoice.thirdId);
    pm.expect(invoice.totalValue).to.eql(expectedInvoice.totalValue);
    pm.expect(invoice.pendingValue).to.eql(expectedInvoice.pendingValue);
    pm.expect(invoice.creationDate).to.eql(expectedInvoice.creationDate);
    pm.expect(invoice.expirationDate).to.eql(expectedInvoice.expirationDate);
});

// 8. Validar regla de negocio derivada del evento Rabbit
pm.test("Pending value is consistent with total value and payments", function () {
    const totalPayFromEvent = 50000;
    pm.expect(invoice.pendingValue).to.eql(
        expectedInvoice.totalValue - totalPayFromEvent
    );
});

