// 1. Código HTTP correcto
pm.test("Status code es 200 OK", function () {
    pm.response.to.have.status(200);
});

// 2. Respuesta exitosa
pm.test("La respuesta indica operación exitosa", function () {
    pm.expect(response.success).to.eql(true);
    pm.expect(response.code).to.eql("OK");
});

// 3. La respuesta contiene una lista de recibos
pm.test("La respuesta contiene un arreglo de recibos", function () {
    pm.expect(response.data).to.be.an("array");
    pm.expect(response.data.length).to.be.greaterThan(0);
});

// 4. Validación de estructura mínima del recibo
pm.test("Cada recibo contiene los campos obligatorios", function () {
    response.data.forEach(receipt => {
        pm.expect(receipt).to.have.property("id");
        pm.expect(receipt).to.have.property("receiptCode");
        pm.expect(receipt).to.have.property("thirdPartyId");
        pm.expect(receipt).to.have.property("paymentMethodId");
        pm.expect(receipt).to.have.property("enterpriseId");
        pm.expect(receipt).to.have.property("receiptTypeId");
        pm.expect(receipt).to.have.property("status");
        pm.expect(receipt).to.have.property("issueDate");
        pm.expect(receipt).to.have.property("totalAmount");
    });
});

// 5. Validación de coherencia del tercero consultado
pm.test("Todos los recibos pertenecen al tercero consultado", function () {
    response.data.forEach(receipt => {
        pm.expect(receipt.thirdPartyId).to.eql(1);
    });
});

// 6. Validación del estado del recibo
pm.test("El recibo tiene un estado válido del negocio", function () {
    const validStatuses = ["FINALIZED", "VOIDED"];
    response.data.forEach(receipt => {
        pm.expect(validStatuses).to.include(receipt.status);
    });
});

// 7. Validación del detalle del recibo
pm.test("El detalle del recibo es un arreglo válido", function () {
    response.data.forEach(receipt => {
        pm.expect(receipt.details).to.be.an("array");
    });
});

