// Parseo de respuesta
const response = pm.response.json();

// 1. Código HTTP
pm.test("Status code es 201", function () {
    pm.response.to.have.status(201);
});

// 2. Respuesta base ApiResponse
pm.test("La respuesta indica operación exitosa", function () {
    pm.expect(response.success).to.eql(true);
    pm.expect(response.code).to.eql("OK");
    pm.expect(response.message)
        .to.eql("Castigo de cartera creado exitosamente.");
});

// 3. Validación estructura DATA
pm.test("La respuesta contiene el objeto data del castigo", function () {
    pm.expect(response.data).to.be.an("object");
});

// 4. Validación datos generales del castigo
pm.test("Los datos del castigo coinciden con la solicitud enviada", function () {
    const data = response.data;
    const requestBody = pm.request.body.raw
        ? JSON.parse(pm.request.body.raw)
        : {};

    pm.expect(data.justification).to.eql(requestBody.justification);
    pm.expect(data.writeOffDate).to.eql(requestBody.writeOffDate);
    pm.expect(data.debitAuxiliaryAccount).to.eql(requestBody.debitAuxiliaryAccount);
    pm.expect(data.debitAuxiliaryAccountId).to.eql(requestBody.debitAuxiliaryAccountId);
    pm.expect(data.thirdId).to.eql(requestBody.thirdId);
    pm.expect(data.costCenterId).to.eql(requestBody.costCenterId);
    pm.expect(data.enterpriseId).to.eql(requestBody.enterpriseId);
});

// 5. Validación estado y campos automáticos
pm.test("El castigo se crea en estado PENDING_CONFIRMATION y con campos generados", function () {
    const data = response.data;

    pm.expect(data.status).to.eql("PENDING_CONFIRMATION");
    pm.expect(data.code).to.be.a("string").and.not.empty;
    pm.expect(data.totalAmount).to.be.a("number").and.greaterThan(0);
});

// 6. Validación detalles del castigo
pm.test("Los detalles del castigo coinciden con las facturas castigadas", function () {
    const data = response.data;
    const requestBody = JSON.parse(pm.request.body.raw);

    pm.expect(data.details).to.be.an("array");
    pm.expect(data.details.length).to.eql(requestBody.details.length);

    data.details.forEach((detail, index) => {
        const reqDetail = requestBody.details[index];

        pm.expect(detail.amountWrittenOff).to.be.a("number");

        pm.expect(detail.invoice).to.be.an("object");
        pm.expect(detail.invoice.id).to.eql(reqDetail.invoiceId);
        pm.expect(detail.invoice.factCode).to.be.a("string");
        pm.expect(detail.invoice.pendingValue).to.be.a("number");
        pm.expect(detail.invoice.accountingAccount).to.be.a("number");
    });
});

// 7. Coherencia del monto castigado
pm.test("El total del castigo coincide con la suma de los valores castigados", function () {
    const data = response.data;

    const totalFromDetails = data.details.reduce(
        (sum, d) => sum + d.amountWrittenOff,
        0
    );

    pm.expect(data.totalAmount).to.eql(totalFromDetails);
});

// Guardar ID del castigo para pruebas posteriores
pm.test("Save created Write-Off ID for subsequent tests", function () {
    pm.expect(response.data, "Response data should exist").to.exist;
    pm.expect(response.data.id, "ID del castigo debe existir").to.be.a("number");

    if (response.data && response.data.id) {
        pm.environment.set("createdWriteOffId", response.data.id);
        console.log(`SUCCESS: Saved createdWriteOffId: ${response.data.id}`);
    }
});

